    fn token_claims_deserializes_standard_claims() {
        let json = r#"{
            "sub": "42",
            "iss": "https://auth.example.com",
            "aud": "https://mcp.example.com/mcp",
            "exp": 1700003600,
            "iat": 1700000000,
            "jti": "token-123",
            "client_id": "client-abc",
            "scope": "commoncal.calendar.metadata.read commoncal.event.read.basic",
            "amr": ["pwd"]
        }"#;
