            claims.scope,
            Some("commoncal.calendar.metadata.read commoncal.event.read.basic".to_string())
        );
        assert_eq!(claims.jti, Some("token-123".to_string()));
        assert_eq!(claims.amr, Some(vec!["pwd".to_string()]));
    }

