    fn token_claims_scope_alias_scp() {
        let json = r#"{
            "sub": "1",
            "iss": "https://auth.example.com",
            "aud": "https://mcp.example.com/mcp",
            "exp": 1700003600,
            "iat": 1700000000,
            "scp": "scope1 scope2"
        }"#;
