        .clone()
        .oneshot(rpc_request(
            "mcal.hajnal.space",
            Some(&token),
            None,
            "initialize",
        ))
        .await
        .unwrap();
    assert_eq!(initialized.status(), StatusCode::OK);
    let session = initialized
        .headers()
        .get("mcp-session-id")
        .unwrap()
        .to_str()
        .unwrap()
        .to_owned();
    decoded_result(initialized).await;
    router
        .clone()
        .oneshot(rpc_request(
